    """Restore cells covered by 3 using the 180-degree symmetric pattern."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 3:
                v = grid[h - 1 - r][w - 1 - c]
                if v == 3:
                    # If the symmetric pair is also covered, use the row's
                    # mirrored counterpart, which carries the repeated pattern.
                    v = grid[r][w - 1 - c]
                out[r][c] = v
    return out
